use vstd::prelude::*;

verus! {

    /// For each query (a, b), computes the minimum number of moves to
    /// transform a into b under the rules:
    ///  - In one move you may add any positive odd integer.
    ///  - In one move you may subtract any positive even integer.
    ///
    /// Specification:
    ///   - If a == b, answer = 0.
    ///   - If a < b, then let d = b - a:
    ///       • if d is odd, answer = 1  (add d in one odd‐add move)
    ///       • else          answer = 2  (sum of two odds)
    ///   - If a > b, then let d = a - b:
    ///       • if d is even, answer = 1 (subtract d in one even‐sub move)
    ///       • else         answer = 2 (add 1, then subtract d+1)
    #[verifier(publish)]
    fn solve(input: Vec<(i8, i8)>) -> Vec<i8>
        ensures |output: &Vec<i8>|
            output.len() == input.len() &&
            forall(|i: usize| i < input.len() ==>
                {
                    let (a, b) = input.index(i);
                    let r = output.index(i);
                    if *a == *b {
                        *r == 0
                    } else if *a < *b {
                        let d = *b - *a;
                        if d % 2 == 1 { *r == 1 } else { *r == 2 }
                    } else {
                        let d = *a - *b;
                        if d % 2 == 0 { *r == 1 } else { *r == 2 }
                    }
                }
            )
    {
        let mut output: Vec<i8> = Vec::new();
        let mut i: usize = 0;
        while i < input.len() {
            invariant!(i <= input.len());
            invariant!(output.len() == i);
            let (a, b) = input.index(i);
            let a = *a;
            let b = *b;
            let moves = if a == b {
                0
            } else if a < b {
                let d = b - a; // positive
                if d % 2 == 1 {
                    1
                } else {
                    2
                }
            } else {
                let d = a - b; // positive
                if d % 2 == 0 {
                    1
                } else {
                    2
                }
            };
            output.push(moves);
            i += 1;
        }
        output
    }
}